function toTitleCase(s){return s.toLowerCase().replace(/\b\w/g, (c) => c.toUpperCase());}function toSentenceCase(s){return s.toLowerCase().replace(/(^\s*\w|[.!?]\s*\w)/g, (c) => c.toUpperCase());}function toCamelCase(s){return s.trim().toLowerCase().replace(/[^a-z0-9]+(.)/g, (_, c) => c.toUpperCase());}function toSnakeCase(s){return s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");}function toKebabCase(s){return s.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");}function executeCaseConvert(){const raw = document.getElementById("case-input").value;const out = document.getElementById("case-result");if (!raw){GAMA.say("idle");return;}GAMA.say("working");setTimeout(() =>{const rows = [ ["UPPERCASE", raw.toUpperCase()], ["lowercase", raw.toLowerCase()], ["Title Case", toTitleCase(raw)], ["Sentence case", toSentenceCase(raw)], ["camelCase", toCamelCase(raw)], ["snake_case", toSnakeCase(raw)], ["kebab-case", toKebabCase(raw)] ];out.innerHTML = rows.map(([label, val]) => `<div><span style="color:var(--phosphor-dim)">${label}:</span> ${val}</div>` ).join("");GAMA.say("success");GAMA.log("Case conversion matrix generated");}, 100);}